def solve(inputs: dict) ->:
    K = inputs['K']-1
    idx,r = 0,[]
    for x in range(1,int(inputs['N'])+1): r.append(x)
    while(len(r)>1):
        del r[(idx+K)%len(r)]
        idx = (idx-K-1+len(r))%len(r)
    return int(r[0])

